class Solution {
    public List<Integer> countSmaller(int[] nums) {
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int u = 0;
        for (int i = 0; i < sorted.length; i++) {
            if (i == 0 || sorted[i] != sorted[i - 1]) sorted[u++] = sorted[i];
        }
        int[] tree = new int[u + 1];
        Integer[] res = new Integer[nums.length];
        for (int i = nums.length - 1; i >= 0; i--) {
            int rank = Arrays.binarySearch(sorted, 0, u, nums[i]) + 1;
            res[i] = query(tree, rank - 1);
            update(tree, rank, 1, u);
        }
        return Arrays.asList(res);
    }
    private void update(int[] tree, int i, int delta, int max) {
        for (; i <= max; i += i & (-i)) tree[i] += delta;
    }
    private int query(int[] tree, int i) {
        int sum = 0;
        for (; i > 0; i -= i & (-i)) sum += tree[i];
        return sum;
    }
}

